				if localNonPersistentFlags.Lookup(flag.Name) != nil {
					if strings.HasPrefix(fmt.Sprintf("--%s", flag.Name), cmdArgs[len(cmdArgs)-1]) {
						fmt.Printf("--%s\n", flag.Name)
